package com.franco.desco.application.salesoperation.service;import com.franco.desco.application.salesoperation.*;import com.franco.desco.application.salesoperation.port.in.SalesOperationUseCase;import com.franco.desco.application.salesoperation.port.out.SalesOperationPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.salesoperation.SalesOperationModels;
public final class SalesOperationApplicationService implements SalesOperationUseCase{private final SalesOperationPersistencePort p;public SalesOperationApplicationService(SalesOperationPersistencePort p){this.p=p;}public AppResult<PageResult<SalesOperationModels.Summary>>list(SalesOperationCommands.ListOperations c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"OPERATIVOS_LISTADOS","OPERATIVOS_NO_LISTADOS",AppStatus.BAD_REQUEST);}public AppResult<SalesOperationModels.Detail>get(SalesOperationCommands.Get c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"OPERATIVO_CONSULTADO","OPERATIVO_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<Long>create(SalesOperationCommands.Create c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.create(c,i,m),"OPERATIVO_CREADO","OPERATIVO_NO_CREADO");}public AppResult<Void>update(SalesOperationCommands.Update c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.update(c,i,m),"OPERATIVO_ACTUALIZADO","OPERATIVO_NO_ACTUALIZADO",AppStatus.BAD_REQUEST);}public AppResult<Void>setZones(SalesOperationCommands.SetZones c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.setZones(c,i,m),"ZONAS_ACTUALIZADAS","ZONAS_NO_ACTUALIZADAS",AppStatus.BAD_REQUEST);}public AppResult<Void>startReception(SalesOperationCommands.Transition c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.startReception(c,i,m),"RECEPCION_INICIADA","RECEPCION_NO_INICIADA",AppStatus.BAD_REQUEST);}public AppResult<Void>close(SalesOperationCommands.Transition c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.close(c,i,m),"OPERATIVO_CERRADO","OPERATIVO_NO_CERRADO",AppStatus.BAD_REQUEST);}public AppResult<Void>cancel(SalesOperationCommands.Transition c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.cancel(c,i,m),"OPERATIVO_CANCELADO","OPERATIVO_NO_CANCELADO",AppStatus.BAD_REQUEST);}}
